def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

import heapq
from collections import defaultdict


def toposort(nodes, edges):
    for src, dst in edges:
        if src == dst:
            raise ValueError("self loop detected")

    adj = defaultdict(set)
    in_degree = {node: 0 for node in nodes}
    seen = set()
    for src, dst in edges:
        if (src, dst) in seen:
            continue
        seen.add((src, dst))
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for neighbor in sorted(adj[node]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")

    return order

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be a positive integer")
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("every weight must be between 1 and limit")
    if not items:
        return []
    batches = []
    current = []
    total = 0
    for name, weight in items:
        if total + weight > limit:
            batches.append(current)
            current = []
            total = 0
        current.append(name)
        total += weight
    if current:
        batches.append(current)
    return batches

def parse_sse(chunks):
    text = b"".join(chunks).decode("utf-8")

    results = []
    current_data = []

    for raw_line in text.split("\n"):
        if raw_line.endswith("\r"):
            raw_line = raw_line[:-1]

        if raw_line == "":
            if current_data:
                event_data = "\n".join(current_data)
                if event_data == "[DONE]":
                    return results
                results.append(event_data)
            current_data = []
            continue

        if raw_line.startswith(":"):
            continue

        idx = raw_line.find(":")
        if idx == -1:
            continue

        field = raw_line[:idx]
        value = raw_line[idx + 1:]
        if value[:1] == " ":
            value = value[1:]

        if field == "data":
            current_data.append(value)

    return results

import math


def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")

    # Zero base: 0 * 2**attempt is 0 for every finite attempt (we avoid the
    # 0 * inf nan trap by never materializing the power for huge attempts),
    # and cap >= 0 so min(cap, 0) == 0.
    if base == 0:
        return 0.0

    # base > 0.  base * 2**attempt overflows float when log2(base) + attempt
    # reaches the ~1024 exponent ceiling.  Rather than materializing a
    # gigantic 2**attempt (impossible for attempt == 10**9), we detect the
    # overflow with a cheap estimate; when detected, base * 2**attempt is
    # effectively +inf and min(cap, +inf) == cap.
    if attempt >= 1024 or math.log2(base) + attempt >= 1023.999999:
        return float(cap)

    # Here the product is guaranteed finite, so 2**attempt stays a small
    # power of two (attempt < 1024) and no huge integer is ever built.
    return min(cap, base * 2 ** attempt)

def fifo_admit(active, queued, budget, slots):
    for reservation in queued:
        if reservation > budget:
            raise ValueError("queued reservation exceeds the whole budget")

    slots_free = slots - len(active)
    tokens_free = budget - sum(active)

    admitted = []
    index = 0
    for reservation in queued:
        if slots_free > 0 and tokens_free >= reservation:
            admitted.append(reservation)
            slots_free -= 1
            tokens_free -= reservation
            index += 1
        else:
            break

    remaining = list(queued[index:])
    return admitted, remaining
